    if (sciErr.iErr) {
      printError(&sciErr, 0);
      return SWIG_ERROR;
    }

    *pfValue = (float *) malloc((*iRows) * (*iCols) * sizeof(float));
    for (i=0; i < (*iRows) * (*iCols); i++)
      (*pfValue)[i] = (float) pdValue[i];

