int SWIG_SciHypermat_AsMat(void *pvApiCtx, int iVarInput, cv::Mat **pMat, char *fname) {
  SciErr sciErr;
  int *piAddrVar = NULL;

  sciErr = getVarAddressFromPosition(pvApiCtx, iVarInput, &piAddrVar);
  if (sciErr.iErr) {
    printError(&sciErr, 0);
    return sciErr.iErr;
  }

  if (isEmptyMatrix(pvApiCtx, piAddrVar)) {
    *pMat = new cv::Mat();
    return SWIG_OK;
  }
  else if (isHypermatType(pvApiCtx, piAddrVar)) {
    int htype = 0;
    int iPrec = 0;
    int ndims = 0;
    int *dims = NULL;
    int w, h, nc, type = 0;
    void *data = NULL;
    int size = 0;

    sciErr = getHypermatType(pvApiCtx, piAddrVar, &htype);
    if (sciErr.iErr) {
      printError(&sciErr, 0);
      return sciErr.iErr;
    }

    if (htype == sci_ints) {
      sciErr = getHypermatOfIntegerPrecision(pvApiCtx, piAddrVar, &iPrec);
      if (sciErr.iErr) {
        printError(&sciErr, 0);
        return sciErr.iErr;
      }

      switch (iPrec) {
        case SCI_UINT8: {
          uint8_t *src = NULL;
          sciErr = getHypermatOfUnsignedInteger8(pvApiCtx, piAddrVar, &dims, &ndims, (unsigned char**)&src);
          if (sciErr.iErr == 0) {
            h = dims[0];
            w = dims[1];
            nc = dims[2];
            size = w * h * nc * sizeof(uint8_t);
            data = malloc(size);
               for (int c = 0; c<nc; c++)      for (int i = 0; i<h; i++)        for (int j = 0; j<w; j++)          ((uint8_t*)data)[c + nc*(i*w + j)] = src[c*w*h + j*h + i];
            type = (nc > 1) ? CV_8UC3 : CV_8UC1;
          }
          break;
        }
        case SCI_INT8: {
          int8_t *src = NULL;
          sciErr = getHypermatOfInteger8(pvApiCtx, piAddrVar, &dims, &ndims, (char**)&src);
          if (sciErr.iErr == 0) {
            h = dims[0];
            w = dims[1];
            nc = dims[2];
            size = w * h * nc * sizeof(int8_t);
            data = malloc(size);
               for (int c = 0; c<nc; c++)      for (int i = 0; i<h; i++)        for (int j = 0; j<w; j++)          ((int8_t*)data)[c + nc*(i*w + j)] = src[c*w*h + j*h + i];
            type = (nc > 1) ? CV_8SC3 : CV_8SC1;
          }
          break;
        }
        case SCI_UINT16: {
          uint16_t *src = NULL;
          sciErr = getHypermatOfUnsignedInteger16(pvApiCtx, piAddrVar, &dims, &ndims, (unsigned short**)&src);
          if (sciErr.iErr == 0) {
            h = dims[0];
            w = dims[1];
            nc = dims[2];
            size = w * h * nc * sizeof(uint16_t);
            data = malloc(size);
               for (int c = 0; c<nc; c++)      for (int i = 0; i<h; i++)        for (int j = 0; j<w; j++)          ((uint16_t*)data)[c + nc*(i*w + j)] = src[c*w*h + j*h + i];
            type = (nc > 1) ? CV_16UC3 : CV_16UC1;
          }
          break;
        }
        case SCI_INT16: {
          int16_t *src = NULL;
          sciErr = getHypermatOfInteger16(pvApiCtx, piAddrVar, &dims, &ndims, (short**)&src);
          if (sciErr.iErr == 0) {
            h = dims[0];
            w = dims[1];
            nc = dims[2];
            size = w * h * nc * sizeof(int16_t);
            data = malloc(size);
               for (int c = 0; c<nc; c++)      for (int i = 0; i<h; i++)        for (int j = 0; j<w; j++)          ((int16_t*)data)[c + nc*(i*w + j)] = src[c*w*h + j*h + i];
            type = (nc > 1) ? CV_16SC3 : CV_16SC1;
          }
          break;
        }
        /*case SCI_UINT32: {
          uint32_t *src = NULL;
          sciErr = getHypermatOfUnsignedInteger32(pvApiCtx, piAddrVar, &dims, &ndims, (unsigned int**)&src);
          if (sciErr.iErr == 0) {
            h = dims[0];
            w = dims[1];
            nc = dims[2];
            size = w * h * nc * sizeof(uint32_t);
            data = malloc(size);
            copy_column_major_planar_to_row_major_pixel_data(uint32_t);
            type = (nc > 1) ? CV_32UC3 : CV_32UC1;
          }
          break;
        }*/
        case SCI_INT32: {
          int32_t *src = NULL;
          sciErr = getHypermatOfInteger32(pvApiCtx, piAddrVar, &dims, &ndims, (int32_t**)&src);
          if (sciErr.iErr == 0) {
            h = dims[0];
            w = dims[1];
            nc = dims[2];
            size = w * h * nc * sizeof(int32_t);
            data = malloc(size);
               for (int c = 0; c<nc; c++)      for (int i = 0; i<h; i++)        for (int j = 0; j<w; j++)          ((int32_t*)data)[c + nc*(i*w + j)] = src[c*w*h + j*h + i];
            type = (nc > 1) ? CV_32SC3 : CV_32SC1;
          }
          break;
        }
      }
    }
    else if (htype == sci_matrix) {
      double *src = NULL;
      sciErr = getHypermatOfDouble(pvApiCtx, piAddrVar, &dims, &ndims, &src);
      if (sciErr.iErr == 0) {
        h = dims[0];
        w = dims[1];
        nc = dims[2];
        size = w * h * nc * sizeof(double);
        data = malloc(size);
           for (int c = 0; c<nc; c++)      for (int i = 0; i<h; i++)        for (int j = 0; j<w; j++)          ((double*)data)[c + nc*(i*w + j)] = src[c*w*h + j*h + i];
        type = (nc > 1) ? CV_64FC3 : CV_64FC1;
      }
    }
    else {
      Scierror(999, _("%s: Wrong type for input argument #%d: A hypermatrix of integer or double is expected.\n"), fname, iVarInput);
      return sciErr.iErr;
    }

    if (sciErr.iErr) {
      printError(&sciErr, 0);
      return sciErr.iErr;
    }

    *pMat = new cv::Mat(h, w, type);
    memcpy((*pMat)->data, data, size);
    free(data);

    return SWIG_OK;
  }
  else if (isVarMatrixType(pvApiCtx, piAddrVar)) {
    int iPrec = 0;
    int w, h, type = 0;
    int nc = 1;
    void *data = NULL;
    int size = 0;

    if (isIntegerType(pvApiCtx, piAddrVar)) {
      sciErr = getMatrixOfIntegerPrecision(pvApiCtx, piAddrVar, &iPrec);
      if(sciErr.iErr) {
        printError(&sciErr, 0);
        return sciErr.iErr;
      }

      switch (iPrec) {
        case SCI_UINT8: {
          uint8_t *src = NULL;
          sciErr = getMatrixOfUnsignedInteger8(pvApiCtx, piAddrVar, &h, &w, (unsigned char**)&src);
          if (sciErr.iErr == 0) {
            size = w * h * sizeof(uint8_t);
            data = malloc(size);
               for (int c = 0; c<nc; c++)      for (int i = 0; i<h; i++)        for (int j = 0; j<w; j++)          ((uint8_t*)data)[c + nc*(i*w + j)] = src[c*w*h + j*h + i];
            type = CV_8UC1;
          }
          break;
        }
        case SCI_INT8: {
          int8_t *src = NULL;
          sciErr = getMatrixOfInteger8(pvApiCtx, piAddrVar, &h, &w, (char**)&src);
          if (sciErr.iErr == 0) {
            size = w * h * sizeof(int8_t);
            data = malloc(size);
               for (int c = 0; c<nc; c++)      for (int i = 0; i<h; i++)        for (int j = 0; j<w; j++)          ((int8_t*)data)[c + nc*(i*w + j)] = src[c*w*h + j*h + i];
            type = CV_8SC1;
          }
          break;
        }
        case SCI_UINT16: {
          uint16_t *src = NULL;
          sciErr = getMatrixOfUnsignedInteger16(pvApiCtx, piAddrVar, &h, &w, (unsigned short**)&src);
          if (sciErr.iErr == 0) {
            size = w * h * sizeof(uint16_t);
            data = malloc(size);
               for (int c = 0; c<nc; c++)      for (int i = 0; i<h; i++)        for (int j = 0; j<w; j++)          ((uint16_t*)data)[c + nc*(i*w + j)] = src[c*w*h + j*h + i];
            type = CV_16UC1;
          }
          break;
        }
        case SCI_INT16: {
          int16_t *src = NULL;
          sciErr = getMatrixOfInteger16(pvApiCtx, piAddrVar, &h, &w, (short**)&src);
          if (sciErr.iErr == 0) {
            size = w * h * sizeof(int16_t);
            data = malloc(size);
               for (int c = 0; c<nc; c++)      for (int i = 0; i<h; i++)        for (int j = 0; j<w; j++)          ((int16_t*)data)[c + nc*(i*w + j)] = src[c*w*h + j*h + i];
            type = CV_16SC1;
          }
          break;
        }
        /*case SCI_UINT32: {
          uint32_t *src = NULL;
          sciErr = getMatrixOfUnsignedInteger32(pvApiCtx, piAddrVar, &h, &w,, (unsigned int**)&src);
          if (sciErr.iErr == 0) {
            size = w * h * sizeof(uint32_t);
            data = malloc(size);
            copy_column_major_planar_to_row_major_pixel_data(uint32_t);
            type = CV_32UC1;
          }
          break;
        }*/
        case SCI_INT32: {
          int32_t *src = NULL;
          sciErr = getMatrixOfInteger32(pvApiCtx, piAddrVar, &h, &w, (int**)&src);
          if (sciErr.iErr == 0) {
            size = w * h * sizeof(int32_t);
            data = malloc(size);
               for (int c = 0; c<nc; c++)      for (int i = 0; i<h; i++)        for (int j = 0; j<w; j++)          ((int32_t*)data)[c + nc*(i*w + j)] = src[c*w*h + j*h + i];
            type = CV_32SC1;
          }
          break;
        }
      }
    }
    else if (isDoubleType(pvApiCtx, piAddrVar)) {
      double *src = NULL;
      sciErr = getMatrixOfDouble(pvApiCtx, piAddrVar, &h, &w, (double**)&src);
      if (sciErr.iErr == 0) {
        size = w * h * sizeof(double);
        data = malloc(size);
           for (int c = 0; c<nc; c++)      for (int i = 0; i<h; i++)        for (int j = 0; j<w; j++)          ((double*)data)[c + nc*(i*w + j)] = src[c*w*h + j*h + i];
        type = CV_64FC1;
      }
    }
    else {
      Scierror(999, _("%s: Wrong type for input argument #%d: A matrix of integer or double is expected.\n"), fname, iVarInput);
      return sciErr.iErr;
    }

    if (sciErr.iErr) {
      printError(&sciErr, 0);
      return sciErr.iErr;
    }

    *pMat = new cv::Mat(h, w, type);
    memcpy((*pMat)->data, data, size);
    free(data);

    return SWIG_OK;
  }
  else {
    Scierror(999, _("%s: Wrong type for input argument #%d: A hypermatrix or a matrix is expected.\n"), fname, iVarInput);
    return sciErr.iErr;
  }
}



int SWIG_SciMListMatOrHypermat_AsMat(void *pvApiCtx, SwigSciObject iVar, cv::Mat **pInMat, int *iNewMat, char *fname) {
  if (SwigScilabPtrToObject(pvApiCtx, iVar, (void**)pInMat, SWIG_Scilab_TypeQuery("cv::Mat *"), 0, fname) == SWIG_OK) {
    *iNewMat = 0;
    return SWIG_OK;
  }
  else {
    if (SWIG_SciHypermat_AsMat(pvApiCtx, iVar, pInMat, fname) == SWIG_OK) {
      *iNewMat = 1;
      return SWIG_OK;
    }
    else {
      return SWIG_ERROR;
    }
  }
}



int SWIG_Check_SciHypermat(void *pvApiCtx, int iVarInput, char *fname) {
  SciErr sciErr;
  int *piAddrVar = NULL;

  sciErr = getVarAddressFromPosition(pvApiCtx, iVarInput, &piAddrVar);
  if (sciErr.iErr) {
    printError(&sciErr, 0);
    return sciErr.iErr;
  }

  if (isEmptyMatrix(pvApiCtx, piAddrVar)) {
    return 1;
  }
  else if (isHypermatType(pvApiCtx, piAddrVar)) {
    int htype;
    sciErr = getHypermatType(pvApiCtx, piAddrVar, &htype);
    if (sciErr.iErr) {
      printError(&sciErr, 0);
      return sciErr.iErr;
    }
    return (htype == sci_ints) || (htype == sci_matrix);
  }
  else if (isVarMatrixType(pvApiCtx, piAddrVar)) {
    return (isDoubleType(pvApiCtx, piAddrVar) || isIntegerType(pvApiCtx, piAddrVar));
  }
  else {
    return 0;
  }
}




